import { test, expect, type Locator, type Page } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

async function scrollToEnd(page: Page, last: Locator) {
  let prevY = Number.NaN;
  let stableCount = 0;
  await expect
    .poll(
      async () => {
        // Мобильный WebKit не поддерживает колесо — прокручиваем контейнер, в котором лежит последний элемент.
        await last.evaluate((el) => {
          let n: HTMLElement | null = el as HTMLElement;
          while (n && !(n.scrollHeight > n.clientHeight + 5 && /auto|scroll/.test(getComputedStyle(n).overflowY))) n = n.parentElement;
          (n ?? document.scrollingElement as HTMLElement).scrollTop += 1500;
        });
        const box = await last.boundingBox();
        const y = box ? box.y : Number.NaN;
        stableCount = y === prevY ? stableCount + 1 : 0;
        prevY = y;
        return stableCount >= 3;
      },
      { timeout: 30_000 },
    )
    .toBe(true);
}

async function expectAboveTabBar(page: Page, last: Locator) {
  await expect(last).toBeVisible();
  const lastBox = await last.boundingBox();
  const tabBoxes = await page.getByRole('tab').evaluateAll((els) =>
    els.map((e) => {
      const r = e.getBoundingClientRect();
      return { y: r.y };
    }),
  );
  const tabBarY = Math.min(...tabBoxes.map((t) => t.y));
  expect(lastBox).not.toBeNull();
  expect(lastBox!.y + lastBox!.height).toBeLessThanOrEqual(tabBarY);
}

test.describe('Главная — прокрутка до конца', () => {
  test('Главная, היסטוריה и חשבון прокручиваются до конца, последний элемент над таб-баром #e9802dc6 @iphone @prod-safe', async ({ page }) => {
    // 1. Open /home, wait for the "ניטורים אחרונים" heading and at least 3 session cards under it
    await page.goto('/home');
    await expect(page.getByRole('heading', { name: 'ניטורים אחרונים' })).toBeVisible();
    const sessionCards = page.getByRole('button', { name: /דק׳ · / });
    await expect(sessionCards.nth(2)).toBeVisible();

    // 2. Scroll the content to the end
    const lastCard = sessionCards.last();
    await scrollToEnd(page, lastCard);

    // 3. Last content element vs bottom tab bar
    await expectAboveTabBar(page, lastCard);

    // 4. Repeat on /history
    await page.getByRole('tab', { name: 'היסטוריה' }).click();
    await expect(page).toHaveURL(/\/history/);
    const lastHistory = page.getByRole('button', { name: 'ניטורים קודמים' });
    await expect(lastHistory).toBeAttached();
    await scrollToEnd(page, lastHistory);
    await expectAboveTabBar(page, lastHistory);

    // 4. Repeat on /account
    await page.getByRole('tab', { name: 'חשבון' }).click();
    await expect(page).toHaveURL(/\/account/);
    const lastAccount = page.getByText('מחיקת החשבון').last();
    await expect(lastAccount).toBeAttached();
    await scrollToEnd(page, lastAccount);
    await expectAboveTabBar(page, lastAccount);
  });
});
